class Editor {
  private content: string;
  constructor(text: string) { this.content = text; }
  save() { return { content: this.content }; }
  restore(snapshot: { content: string }) { this.content = snapshot.content; }
}

class Document {
  private text = '';
  createMemento() { return { text: this.text }; }
  restore(m: { text: string }) { this.text = m.text; }
}
class Caretaker {
  private history: any[] = [];
  push(doc: Document) { this.history.push(doc.createMemento()); }
}

// Version A: public snapshot object
class EditorA {
  private text = '';
  createSnapshot() { return { text: this.text, cursor: 0 }; }
  restore(s: any) { this.text = s.text; }
}

// Version B: opaque snapshot with restoration closure
class EditorB {
  private text = '';
  createSnapshot() {
    const state = { text: this.text };
    return { restore: (target: EditorB) => { target.text = state.text; } };
  }
}
